//! Supported eldenring.exe builds, the exe addresses mw2er's own code uses per build, and the boot preflight that
//! checks every address of the selected build on the LOADED image before anything game-related runs
//! (port to 2.7.2.0, MODLOG 2026-10-20).
//!
//! The DLL (`mw2er::version_gate`) maps the exe's version resource to an [`ExeBuild`] (pure decision in
//! [`crate::gate`]), then runs [`preflight`] over that build's site table ([`crate::exe_sites`], generated by
//! `tools/scripts/exe_sites.py` from the exe file) through an [`ImageView`] of the loaded module. Any failing site
//! keeps the DLL inert. Only after that does it hand the build's [`OwnAddrs`] to the hooks.

use crate::exe_sites::{SITES_2710, SITES_2720};
use crate::gate::Quad;

/// A supported eldenring.exe build (WW / English version resource; the fromsoftware-rs table of the same name).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExeBuild {
    /// FileVersion 2.7.1.0 (Elden Ring 1.17.1, Steam build 25080141): the vendored `rva_ww.rs`.
    Ww2710,
    /// FileVersion 2.7.2.0 (Steam build 25827938, auto-update 2026-10-20): `rva_ww2720.rs` (vendor patch 0004).
    Ww2720,
}

impl ExeBuild {
    pub const ALL: [ExeBuild; 2] = [ExeBuild::Ww2710, ExeBuild::Ww2720];

    pub const fn version(self) -> Quad {
        match self {
            ExeBuild::Ww2710 => (2, 7, 1, 0),
            ExeBuild::Ww2720 => (2, 7, 2, 0),
        }
    }

    /// The build whose FileVersion this is (`None` = unsupported).
    pub fn from_version(v: Quad) -> Option<ExeBuild> {
        Self::ALL.into_iter().find(|b| b.version() == v)
    }

    /// The fromsoftware-rs table name (`ERGameVersion` variant), logged as `table=`.
    pub const fn table_name(self) -> &'static str {
        match self {
            ExeBuild::Ww2710 => "Ww2710",
            ExeBuild::Ww2720 => "Ww2720",
        }
    }

    pub const fn own(self) -> &'static OwnAddrs {
        match self {
            ExeBuild::Ww2710 => &OWN_2710,
            ExeBuild::Ww2720 => &OWN_2720,
        }
    }

    pub const fn sites(self) -> &'static [Site] {
        match self {
            ExeBuild::Ww2710 => SITES_2710,
            ExeBuild::Ww2720 => SITES_2720,
        }
    }

    /// The PE header's `(TimeDateStamp, SizeOfImage)` of this build (review 2026-10-20: pins the build itself, so an
    /// exe with the same version number but other code cannot pass on the section-kind-only sites, e.g. the `.data`
    /// globals). 2.7.1.0 [V live: every `VERSION PASS` line of this PC and the friend's, 2026-10-14..19];
    /// 2.7.2.0 [V exe file f9118fea2cfd, read only].
    pub const fn header(self) -> (u32, u32) {
        match self {
            ExeBuild::Ww2710 => (0x6a96_b418, 0x05e0_da00),
            ExeBuild::Ww2720 => (0x6aab_f7e7, 0x05df_d600),
        }
    }
}

/// `Err` unless the loaded image's header is exactly `build`'s (see [`ExeBuild::header`]).
pub fn check_header(build: ExeBuild, time_date_stamp: u32, size_of_image: u32) -> Result<(), String> {
    let (t, s) = build.header();
    if (time_date_stamp, size_of_image) == (t, s) {
        Ok(())
    } else {
        let want = format!("0x{t:08x} / 0x{s:x}");
        Err(format!(
            "header timedatestamp=0x{time_date_stamp:08x} sizeofimage=0x{size_of_image:x} is not the {} build's ({want})",
            build.table_name()
        ))
    }
}

/// How mw2er depends on a code site, i.e. what a byte difference on the loaded image means (review 2026-10-20).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role {
    /// mw2er installs a hook here (MinHook needs the exact prologue): any difference is fatal.
    Hook,
    /// mw2er calls it through fromsoftware-rs: exact bytes, or another module's 5-byte `jmp rel32` detour over the
    /// first bytes with the rest of the window intact (then calling it is what the game itself does; WARN).
    Call,
    /// fromsoftware-rs has an RVA for it, but mw2er never calls it (no crate API reaching it is used; a source test
    /// pins that). A byte difference is a WARN, never inert; the section kind is still required.
    Unused,
    /// Not a code window (vtables, globals): the check itself is the whole verdict.
    Data,
}

/// Crate code sites mw2er never reaches: `CSEzDraw::draw_*` (rend_man), `CSMenuManImp::display_status_message`,
/// `CSActionButtonManImp::present_action_button`, `CSWorldGeomManBlockData::spawn_geometry` (2 RVAs) and
/// `DLUserInputManagerImpl` (`obtain_dl_user_input_manager`). Seamless Co-op loads before mw2er and Arxan patches code
/// at run time; neither must be able to make mw2er inert through a function it does not use.
pub const UNUSED_CRATE_CODE: [&str; 11] = [
    "cs_action_button_man_execute_action_button",
    "cs_ez_draw_draw_capsule",
    "cs_ez_draw_draw_dodecadron",
    "cs_ez_draw_draw_line",
    "cs_ez_draw_draw_sphere",
    "cs_ez_draw_draw_triangle",
    "cs_ez_draw_draw_wedge",
    "cs_menu_man_imp_display_status_message",
    "initialize_spawn_geometry_request",
    "obtain_dl_user_input_manager",
    "spawn_geometry",
];

/// Crate code sites mw2er calls (`ChrInsExt::apply_speffect` / `remove_speffect`, `CSBulletManager::spawn_bullet`,
/// `CSPhysWorld::cast_ray`, `CSTaskImp::run_recurring` -> `register_task`).
pub const CALLED_CRATE_CODE: [&str; 5] = [
    "chr_ins_apply_speffect",
    "chr_ins_remove_speffect",
    "cs_bullet_manager_spawn_bullet",
    "cs_phys_world_cast_ray",
    "register_task",
];

/// The [`Role`] of a site.
pub fn role(s: &Site) -> Role {
    match (s.group, s.check) {
        (Group::Own, Check::Code(_) | Check::Exec) => Role::Hook,
        (Group::Crate, Check::Code(_) | Check::Exec) if UNUSED_CRATE_CODE.contains(&s.name) => Role::Unused,
        (Group::Crate, Check::Code(_) | Check::Exec) => Role::Call,
        _ => Role::Data,
    }
}

/// A 5-byte `jmp rel32` written over the window's start by another module, the rest of the window unchanged.
fn is_jmp_detour(got: &[u8], want: &[u8]) -> bool {
    got.len() == want.len() && got.len() > 8 && got[0] == 0xe9 && want[0] != 0xe9 && got[5..] == want[5..]
}

/// The exe addresses (RVAs) mw2er's own code uses outside fromsoftware-rs, with the prologue bytes each hook checks
/// right before it installs (MinHook needs the exact bytes; the preflight checked a 16-byte window already).
#[derive(Debug, PartialEq, Eq)]
pub struct OwnAddrs {
    /// ER's camera-step update (erfps2 `CAMERA_STEP_UPDATE_RVA`).
    pub camera_step: usize,
    pub camera_step_prologue: &'static [u8],
    /// ER's per-frame `ChrExFollowCam` update (erfps2 `UPDATE_FOLLOW_CAM_RVA`); the last 6 prologue bytes pin
    /// `cmp byte ptr [rcx+0x240]` (camera_auto_rotation).
    pub follow_cam: usize,
    pub follow_cam_prologue: &'static [u8],
    /// The `CAM_WALL_RECOVERY` bool in `.data` (erfps2 `CAM_WALL_RECOVERY_RVA`).
    pub cam_wall_recovery: usize,
    /// Scaleform GFx D3D12 HAL BeginScene / EndScene (vtable slots 59 / 60), the C3 UI probe.
    pub begin_scene: usize,
    pub begin_scene_prologue: &'static [u8],
    pub end_scene: usize,
    pub end_scene_prologue: &'static [u8],
    /// `CS::CSCollisionFilter` vtable (C3 static layer table check).
    pub filter_vtable: usize,
    /// `CS::ChrCam` vtable (the vendored crate's `chr_cam_vmt`): finds `WorldChrMan.chr_cam` at run time.
    pub chr_cam_vmt: usize,
    /// Bytes `WorldChrMan` grew between `main_player` and `chr_cam` against the vendored layout (2.7.1.0); applied
    /// to `chr_cam` and the fields after it. The run-time ChrCam vtable scan confirms or replaces it.
    pub wcm_tail_shift: usize,
    /// C4 (docs/C4_UI_DESIGN.md 7): ER's UI frame begin / end and the Scaleform HAL facts the probe and the injection
    /// read. `None` = this build has no verified values (nothing is hooked; `UI inject off why=build`).
    pub scaleform_ui: Option<ScaleformUi>,
    /// C6 (docs/C6_HOLD_DESIGN.md 4.1, work/c6/bones.md 2 [V RTTI]): `CSFD4LocationMtx43ArrayEntity` (the bone array
    /// behind `CSFD4ModelItem+0x640`) and `CSFD4LocationMtx44ChrEntity` (`ChrCtrl+0x2F8`, the drawn body matrix) vtables.
    /// `None` = not verified on this build: hand mode falls back to the fixed offset (`HOLD fallback reason=exe`).
    pub mtx43_array_vtable: Option<usize>,
    pub mtx44_chr_vtable: Option<usize>,
    /// C6 attach 2 (work/c6/attach2.md 1 [V RTTI, re-read 2026-10-21]): `CSChrAsmModelIns` (`PlayerIns+0x648`), `CSPartsModelIns`
    /// (its 27 model slots; slot 11 = model 0 of the active right weapon) and `CSFD4LocationMtx44Entity` (a parts model's
    /// location matrix). `None` = the weapon model is never read (hand mode uses the hand bone).
    pub chr_asm_model_vtable: Option<usize>,
    pub parts_model_vtable: Option<usize>,
    pub mtx44_entity_vtable: Option<usize>,
    /// C6 depth probe (work/c6/depth3.md 1, docs/C6_HOLD_DESIGN.md 13.3): the read-only chain to ER's scene depth buffer.
    /// `None` = not verified on this build (`DEPTH probe off why=build`).
    pub er_depth: Option<crate::er_depth::ErDepthAddrs>,
    /// C6 round 6 (work/c6/aim6.md, docs 14.8): ER's precision-shooting getter and its camera / reticle call sites.
    /// `None` = not read on this build (`HOLD aim cam unavailable reason=build`: ER's aim camera as round 5).
    pub aim_cam: Option<crate::aim_cam::AimCamAddrs>,
    /// C6 part 16 (work/c6/xbow8.md 2.2): ER's equip functions the crossbow carrier calls (pinned before the first call).
    /// `None` = not read on this build (`HOLD xbow off why=version`).
    pub carrier: Option<crate::carrier::CarrierAddrs>,
}

/// C4: field offsets the UiBegin chain reads, each pinned by an instruction of UiBegin in `c4_static.py`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct UiLayout {
    /// `owner+0x968` = the HAL (`48 8b 89 68 09 00 00`).
    pub owner_hal: usize,
    /// `owner+0xBE0` = movies to draw this frame (`48 83 bb e0 0b 00 00 00`).
    pub owner_movies: usize,
    /// HAL render thread id (`hal+0x50`) and flags (`hal+0x58`: 1 ModeSet, 2 InFrame, 4 InScene).
    pub hal_rtid: usize,
    pub hal_flags: usize,
    /// HAL device / direct queue / current command list (`48 8b 8f 20 14 00 00`).
    pub hal_device: usize,
    pub hal_queue: usize,
    pub hal_list: usize,
    /// `S = [G + 0x128]` (a load: `48 8b 88 28 01 00 00`).
    pub s_off: usize,
    /// `[S+0xF0]` scene image, `[S+0x100]` UI layer, the HDR bytes `S+0x13c` / `S+0x13e`.
    pub scene: usize,
    pub layer: usize,
    pub hdr_a: usize,
    pub hdr_b: usize,
    /// `this = sel + 0x70` (`48 8d 48 70`), `res = [[obj + 8] + 0x20]` (`48 8b 4b 08 48 8b 51 20`).
    pub obj: usize,
    pub wrap: usize,
    pub res: usize,
}

/// C4: one build's UiBegin / UiEnd hooks and the globals around them (RVAs).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ScaleformUi {
    /// ER's UI frame begin (owner in rcx): SetRenderTarget, BeginFrame, the `0xC0 -> 4` barrier on the UI target.
    pub ui_begin: usize,
    pub ui_begin_prologue: &'static [u8],
    /// The reverse barriers, then EndFrame.
    pub ui_end: usize,
    pub ui_end_prologue: &'static [u8],
    /// FromSoftware's HAL subclass vtable (the live object's; ctor 0x140eb8d20).
    pub fs_hal_vtable: usize,
    /// The pointer global G (`.data`); `S = [G + s_off]`.
    pub g_render: usize,
    /// ER's DIRECT queue object (`.data`; +8 = its ID3D12CommandQueue*), logged only.
    pub direct_queue: usize,
    pub layout: UiLayout,
    /// C4.1 (docs/C4_1_DESIGN.md 3.2): the render thread, the read-only target chain and the composite facts.
    pub ui41: Ui41,
    /// C4.1: the UI layer's alpha convention, pinned from a probe run (`UI probe41 sample .. conv=`). `None` until the
    /// run is recorded in MODLOG: the C4.1 injection then never draws early (`alpha_unknown`). The probe ignores it.
    pub layer_alpha: Option<crate::c4::LayerAlpha>,
}

/// C4.1 (docs/C4_1_DESIGN.md 1.2 / 3.2): RVAs (`*_vt`, `*_slot*`, `sel_vt_count`) and field offsets of the
/// read-only chain `sel -> T / arr -> obj -> res`, ER's render-thread id and the UI composite's inputs. Every value is
/// pinned against the exe file by `tests/c4_real_exe.rs` (`c41_addrs_real_exe_2720`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Ui41 {
    /// `byte [G+0x11c]` != 0: ER's multithreaded render mode (`cmp byte ptr [rcx+11Ch],0` at 0x1419ed8ea).
    pub g_mt: usize,
    /// `[[G+0x6d0]+0x14]`: the render thread's id, what ER passes to InitHAL (`mov rax,[rcx+6D0h]; mov edi,[rax+14h]`
    /// at 0x140d7b777).
    pub g_rt: usize,
    pub rt_tid: usize,
    /// `[sel]`: GXBS::GXRenderTarget2D's primary vtable; its slot 7 (`+0x38`, the image count) is `sel_vt_count`.
    pub sel_vt: usize,
    pub sel_vt_count: usize,
    pub sel_count_slot: usize,
    /// `[sel+0x70]` (`UiLayout::obj`): the secondary vtable; slot 0 (index lookup) / slot 1 (the C4 "getter").
    pub sub_vt: usize,
    pub sub_slot0: usize,
    pub sub_slot1: usize,
    /// `T = [sel+0x40]` (the getter's `cmp qword [rcx-30h],0`), `arr = [sel+0x78]` (slot 0's `[rcx+8]`).
    pub sel_tex: usize,
    pub sel_arr: usize,
    /// count = `[T+0x38] ? u32 [[[T+0x38]+8]+8] : u8 [T+0x46]` (0x141e89850 with rcx = T+0x20).
    pub tex_desc: usize,
    pub desc_data: usize,
    pub desc_count: usize,
    pub tex_count: usize,
    /// ER's RTV handle of the image: `[obj+0x10]` (HAL init `lea rdx,[r15+10h]` at 0x140d7b8f3).
    pub obj_rtv: usize,
    /// The cross-check: `rt = [owner+0xdd0]`, `rtData = [rt+0x20]`, `u32 [rtData+0x20]` = format,
    /// `[rtData+0x28]` = ER's RTV handle (FS CreateRenderTarget 0x140ebb160).
    pub owner_rt: usize,
    pub rt_data: usize,
    pub rtdata_fmt: usize,
    pub rtdata_rtv: usize,
    /// The composite's inputs: `byte [G+0xeb9]` (SDR2HDR), `f32 [G+0xed0] / [G+0xed4]` (render scale),
    /// `byte [[G+0x740]+8]` (shaders ready).
    pub g_eb9: usize,
    pub g_scale: usize,
    pub g_shaders: usize,
    pub shaders_ready: usize,
}

