const SUB_SLOT1_2720: [u8; 16] = [0x48, 0x83, 0xec, 0x28, 0x48, 0x83, 0x79, 0xd0, 0x00, 0x48, 0xc7, 0x44, 0x24, 0x30, 0x00, 0x00];

/// C4.1: the chain's code / vtable sites (checked on the loaded image with the probe on, after the C4 sites; never in
/// the boot preflight). The vtables carry RTTI, so they are `Vmt` (stronger than the design's `VtableNoRtti`).
pub fn scaleform_ui41_sites(build: ExeBuild) -> Vec<Site> {
    let Some(u) = build.own().scaleform_ui else { return Vec::new() };
    let c = u.ui41;
    let (count, slot0, slot1): (&'static [u8], &'static [u8], &'static [u8]) = match build {
        ExeBuild::Ww2720 => (&SEL_COUNT_2720, &SUB_SLOT0_2720, &SUB_SLOT1_2720),
        ExeBuild::Ww2710 => return Vec::new(),
    };
    let own = |name, rva: usize, check| Site { name, rva: rva as u32, check, group: Group::Own, conf: Conf::Verified };
    vec![
        own("scaleform_sel_vtable", c.sel_vt, Check::Vmt(GX_RENDER_TARGET_2D)),
        own("scaleform_sub_vtable", c.sub_vt, Check::Vmt(GX_RENDER_TARGET_2D)),
        own("scaleform_sel_count", c.sel_vt_count, Check::Code(count)),
        own("scaleform_sub_slot0", c.sub_slot0, Check::Code(slot0)),
        own("scaleform_sub_slot1", c.sub_slot1, Check::Code(slot1)),
    ]
}

/// RTTI names of the C6 depth chain's vtables (2.7.2.0 COLs, work/c6/depth4/rtti.py).
pub const GX_RENDERING_SYSTEM: &str = ".?AVGXRenderingSystem@GXSR@@";
pub const GX_SCENE_CONTEXT: &str = ".?AVGXSceneContext@GXSR@@";
pub const GX_DEPTH_STENCIL_BUFFER: &str = ".?AVGXDepthStencilBuffer@GXBS@@";

/// C6 depth probe: the chain's sites (checked on the loaded image only with `[coop] probe_er_depth`; never in the boot
/// preflight). The count slot is the same function as the C4.1 `scaleform_sel_count` (GXRenderTarget2D and
/// GXDepthStencilBuffer share slot 7).
pub fn er_depth_sites(build: ExeBuild) -> Vec<Site> {
    let Some(a) = build.own().er_depth else { return Vec::new() };
    let count: &'static [u8] = match build {
        ExeBuild::Ww2720 => &SEL_COUNT_2720,
        ExeBuild::Ww2710 => return Vec::new(),
    };
    let own = |name, rva: usize, check| Site { name, rva: rva as u32, check, group: Group::Own, conf: Conf::Verified };
    vec![
        own("er_depth_rs_global", a.rs_global, Check::Writable),
        own("er_depth_rs_vtable", a.rs_vt, Check::Vmt(GX_RENDERING_SYSTEM)),
        own("er_depth_ctx_vtable", a.ctx_vt, Check::Vmt(GX_SCENE_CONTEXT)),
        own("er_depth_ctx_vtable2", a.ctx_vt2, Check::Vmt(GX_SCENE_CONTEXT)),
        own("er_depth_dsb_vtable", a.dsb_vt, Check::Vmt(GX_DEPTH_STENCIL_BUFFER)),
        own("er_depth_count_fn", a.count_fn, Check::Code(count)),
    ]
}

