/// C4: the sites of a build's [`ScaleformUi`], checked on the loaded image only when the probe or the injection is
/// enabled (never part of the boot preflight: with `[ui]` off nothing changes, and a module that detoured UiBegin can
/// never make the whole DLL inert; the hook install re-checks its prologue and skips instead).
pub fn scaleform_ui_sites(build: ExeBuild) -> Vec<Site> {
    let Some(u) = build.own().scaleform_ui else { return Vec::new() };
    let own = |name, rva: usize, check| Site { name, rva: rva as u32, check, group: Group::Own, conf: Conf::Verified };
    vec![
        own("scaleform_ui_begin", u.ui_begin, Check::Code(u.ui_begin_prologue)),
        own("scaleform_ui_end", u.ui_end, Check::Code(u.ui_end_prologue)),
        own("scaleform_fs_hal_vtable", u.fs_hal_vtable, Check::VtableNoRtti),
        own("scaleform_g_render", u.g_render, Check::Writable),
        own("scaleform_direct_queue", u.direct_queue, Check::Writable),
    ]
}

