/// What the preflight checks at a site.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Check {
    /// The loaded bytes at the RVA equal these (the exe file's bytes).
    Code(&'static [u8]),
    /// A vtable with an RTTI locator: `[rva-8]` -> COL (signature 1, pSelf == its own RVA) -> type name == this.
    Vmt(&'static str),
    /// A vtable without RTTI: in a read-only section, slots 0 and 1 point into an executable section.
    VtableNoRtti,
    /// Resolves into an executable section (no bytes known).
    Exec,
    /// Resolves into a writable, non-executable section (a global).
    Writable,
    /// Resolves into a read-only data section.
    ReadOnly,
}

/// Whose address it is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Group {
    /// A fromsoftware-rs RVA (vendored table of the build).
    Crate,
    /// One of ours ([`OwnAddrs`]).
    Own,
}

/// How the RVA itself was established.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Conf {
    /// Unique signature / RTTI class / pinned bytes from the exe file.
    Verified,
    /// The mapper's first of several matches (2.7.2.0), or a section kind without bytes (2.7.1.0).
    Inferred,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Site {
    pub name: &'static str,
    pub rva: u32,
    pub check: Check,
    pub group: Group,
    pub conf: Conf,
}

/// Section characteristics bits.
pub const SCN_EXEC: u32 = 0x2000_0000;
pub const SCN_READ: u32 = 0x4000_0000;
pub const SCN_WRITE: u32 = 0x8000_0000;

/// The loaded image as the preflight sees it (the DLL: the live module with non-faulting reads; tests: the exe file
/// mapped by section).
pub trait ImageView {
    /// The image's actual base (pointers inside the image are relocated to it).
    fn base(&self) -> u64;
    fn size_of_image(&self) -> u32;
    /// Characteristics of the section holding `rva` (`None` = no section).
    fn section_flags(&self, rva: u32) -> Option<u32>;
    /// Fills `out` from `rva`; false when any byte is unreadable.
    fn read(&self, rva: u32, out: &mut [u8]) -> bool;
}

fn read_u32(img: &dyn ImageView, rva: u32) -> Option<u32> {
    let mut b = [0u8; 4];
    img.read(rva, &mut b).then(|| u32::from_le_bytes(b))
}

fn read_u64(img: &dyn ImageView, rva: u32) -> Option<u64> {
    let mut b = [0u8; 8];
    img.read(rva, &mut b).then(|| u64::from_le_bytes(b))
}

/// RVA of an image pointer (`None` outside the image).
fn ptr_rva(img: &dyn ImageView, va: u64) -> Option<u32> {
    let rva = va.checked_sub(img.base())?;
    (rva < u64::from(img.size_of_image())).then_some(rva as u32)
}

fn kind_ok(flags: Option<u32>, want: Check) -> bool {
    let Some(f) = flags else { return false };
    let (x, w, r) = (f & SCN_EXEC != 0, f & SCN_WRITE != 0, f & SCN_READ != 0);
    match want {
        Check::Exec | Check::Code(_) => x,
        Check::Writable => w && !x,
        Check::ReadOnly | Check::Vmt(_) | Check::VtableNoRtti => r && !w && !x,
    }
}

/// Checks one site; `Err` says why it failed.
pub fn check_site(img: &dyn ImageView, s: &Site) -> Result<(), String> {
    let rva = s.rva;
    if rva == 0 || rva >= img.size_of_image() {
        return Err(format!("rva 0x{rva:x} unresolved (outside the image)"));
    }
    let flags = img.section_flags(rva);
    if !kind_ok(flags, s.check) {
        return Err(format!("rva 0x{rva:x} in a section with characteristics {} (want {:?})", fmt_flags(flags), kind_of(s.check)));
    }
    match s.check {
        Check::Code(want) => {
            let mut got = [0u8; 32];
            let n = want.len().min(got.len());
            if n != want.len() || !img.read(rva, &mut got[..n]) {
                return Err(format!("rva 0x{rva:x} unreadable"));
            }
            if got[..n] != *want {
                return Err(format!("bytes at 0x{rva:x} {} != {}", hex(&got[..n]), hex(want)));
            }
            Ok(())
        }
        Check::Vmt(want) => {
            let col_va = read_u64(img, rva.wrapping_sub(8)).ok_or_else(|| format!("vtable[-1] at 0x{rva:x} unreadable"))?;
            let col = ptr_rva(img, col_va).ok_or_else(|| format!("vtable[-1] 0x{col_va:x} outside the image"))?;
            let sig = read_u32(img, col);
            let td = read_u32(img, col + 12);
            let me = read_u32(img, col + 20);
            if sig != Some(1) || me != Some(col) {
                return Err(format!("no RTTI locator at 0x{col:x} (signature {sig:?}, self {me:?})"));
            }
            let td = td.ok_or("type descriptor unreadable")?;
            let mut name = [0u8; 160];
            let n = want.len() + 1;
            if n > name.len() || !img.read(td.wrapping_add(16), &mut name[..n]) {
                return Err(format!("type name at 0x{td:x} unreadable"));
            }
            if &name[..want.len()] != want.as_bytes() || name[want.len()] != 0 {
                let got = String::from_utf8_lossy(&name[..n]).trim_end_matches('\0').to_string();
                return Err(format!("RTTI type {got:?} != {want:?}"));
            }
            Ok(())
        }
        Check::VtableNoRtti => {
            for slot in [0u32, 8] {
                let va = read_u64(img, rva + slot).ok_or_else(|| format!("vtable slot at 0x{:x} unreadable", rva + slot))?;
                let target = ptr_rva(img, va).ok_or_else(|| format!("vtable slot 0x{va:x} outside the image"))?;
                if !kind_ok(img.section_flags(target), Check::Exec) {
                    return Err(format!("vtable slot 0x{va:x} does not point into code"));
                }
            }
            Ok(())
        }
        Check::Exec | Check::Writable | Check::ReadOnly => Ok(()),
    }
}

fn kind_of(c: Check) -> &'static str {
    match c {
        Check::Exec | Check::Code(_) => "executable",
        Check::Writable => "writable data",
        _ => "read-only data",
    }
}

fn fmt_flags(f: Option<u32>) -> String {
    f.map_or("none".into(), |f| format!("0x{f:08x}"))
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect::<Vec<_>>().join(" ")
}

/// Result of [`preflight`].
#[derive(Debug, Default, PartialEq, Eq)]
pub struct Preflight {
    pub checked: usize,
    pub code: usize,
    pub vmt: usize,
    /// `name: why` of every failing site (empty = PASS).
    pub failures: Vec<String>,
    /// `name: why` of every site that differs in a way mw2er tolerates ([`Role::Unused`] bytes, a [`Role::Call`]
    /// detour). Logged as WARN; they do not fail the preflight.
    pub warnings: Vec<String>,
    /// Sites whose RVA is only inferred (they still passed their check).
    pub inferred: Vec<&'static str>,
}

impl Preflight {
    pub fn passed(&self) -> bool {
        self.failures.is_empty() && self.checked > 0
    }

    /// `sites=113 code=20 vmt=83 inferred=4 warn=0` (the VERSION PASS line's tail).
    pub fn summary(&self) -> String {
        format!(
            "sites={} code={} vmt={} inferred={} warn={}",
            self.checked,
            self.code,
            self.vmt,
            self.inferred.len(),
            self.warnings.len()
        )
    }
}

/// Checks every site of `build` on `img`; a failing site fails the preflight unless its [`Role`] tolerates it.
pub fn preflight(build: ExeBuild, img: &dyn ImageView) -> Preflight {
    preflight_sites(build.sites(), img)
}

/// [`preflight`] over an explicit site list.
pub fn preflight_sites(sites: &[Site], img: &dyn ImageView) -> Preflight {
    let mut p = Preflight::default();
    for s in sites {
        p.checked += 1;
        match s.check {
            Check::Code(_) => p.code += 1,
            Check::Vmt(_) | Check::VtableNoRtti => p.vmt += 1,
            _ => {}
        }
        let Err(e) = check_site(img, s) else {
            if s.conf == Conf::Inferred {
                p.inferred.push(s.name);
            }
            continue;
        };
        // The address itself (inside the image, executable section) is required for every role.
        let kind_ok = check_site(img, &Site { check: Check::Exec, ..*s }).is_ok();
        let tolerated = match (role(s), s.check) {
            (Role::Unused, _) if kind_ok => Some(format!("{}: {e} (unused by mw2er)", s.name)),
            (Role::Call, Check::Code(want)) if kind_ok => {
                let mut got = [0u8; 32];
                let n = want.len().min(got.len());
                (img.read(s.rva, &mut got[..n]) && is_jmp_detour(&got[..n], want))
                    .then(|| format!("{}: detoured by another module (jmp rel32 over the first 5 bytes, rest intact)", s.name))
            }
            _ => None,
        };
        match tolerated {
            Some(w) => p.warnings.push(w),
            None => p.failures.push(format!("{}: {e}", s.name)),
        }
    }
    p
}

/// The site of `name` in `build`'s table.
pub fn site(build: ExeBuild, name: &str) -> Option<&'static Site> {
    build.sites().iter().find(|s| s.name == name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exe_build_versions_and_tables() {
        assert_eq!(ExeBuild::from_version((2, 7, 1, 0)), Some(ExeBuild::Ww2710));
        assert_eq!(ExeBuild::from_version((2, 7, 2, 0)), Some(ExeBuild::Ww2720));
        assert_eq!(ExeBuild::from_version((2, 7, 1, 1)), None);
        assert_eq!(ExeBuild::from_version((2, 7, 3, 0)), None);
        for b in ExeBuild::ALL {
            let own = b.own();
            let names: Vec<&str> = b.sites().iter().map(|s| s.name).collect();
            let mut dedup = names.clone();
            dedup.sort_unstable();
            dedup.dedup();
            assert_eq!(dedup.len(), names.len(), "{b:?}: duplicate site names");
            assert_eq!(b.sites().iter().filter(|s| s.group == Group::Crate).count(), 107, "{b:?}: 107 crate RVAs");
            // every own address is a site of the same build with the matching kind
            for (n, rva, pro) in [
                ("camera_step", own.camera_step, Some(own.camera_step_prologue)),
                ("follow_cam", own.follow_cam, Some(own.follow_cam_prologue)),
                ("scaleform_begin_scene", own.begin_scene, Some(own.begin_scene_prologue)),
                ("scaleform_end_scene", own.end_scene, Some(own.end_scene_prologue)),
                ("cam_wall_recovery", own.cam_wall_recovery, None),
                ("cs_collision_filter_vmt", own.filter_vtable, None),
            ] {
                let s = site(b, n).unwrap_or_else(|| panic!("{b:?}: no site {n}"));
                assert_eq!((s.rva as usize, s.group), (rva, Group::Own), "{b:?} {n}");
                if let (Some(pro), Check::Code(win)) = (pro, s.check) {
                    assert!(win.starts_with(pro), "{b:?} {n}: the preflight window starts with the hook prologue");
                }
            }
        }
        // the moved own addresses (2.7.2.0) and the unchanged ones
        assert_eq!((OWN_2710.cam_wall_recovery, OWN_2720.cam_wall_recovery), (0x3b19c80, 0x3b1cc80));
        assert_eq!((OWN_2720.begin_scene, OWN_2720.end_scene, OWN_2720.filter_vtable), (0x115fda0, 0x115ff00, 0x2b96ee0));
        assert_eq!((OWN_2720.camera_step, OWN_2720.follow_cam), (OWN_2710.camera_step, OWN_2710.follow_cam));
        // every 2.7.2.0 crate code / vtable site carries bytes or an RTTI name (no section-only crate code)
        assert!(SITES_2720.iter().all(|s| s.check != Check::Exec), "2.7.2.0 code sites all carry bytes");
        assert_eq!(site(ExeBuild::Ww2720, "cs_phys_world_cast_ray").map(|s| s.rva), Some(0xc722c0));
        assert_eq!(site(ExeBuild::Ww2710, "cs_phys_world_cast_ray").map(|s| s.rva), Some(0xc71e00));
    }

    #[test]
    fn c4_addrs_tables_and_sites() {
        // 2.7.2.0 has the C4 table, 2.7.1.0 none (the exe is gone; no guessed shifts)
        assert_eq!(OWN_2720.scaleform_ui, Some(SCALEFORM_UI_2720));
        assert_eq!(OWN_2710.scaleform_ui, None);
        // C6: the bone-array / chr-matrix vtables on 2.7.2.0 only
        assert_eq!((OWN_2720.mtx43_array_vtable, OWN_2720.mtx44_chr_vtable), (Some(0x2b70c78), Some(0x2b70d48)));
        assert_eq!((OWN_2710.mtx43_array_vtable, OWN_2710.mtx44_chr_vtable), (None, None));
        assert_eq!((OWN_2720.chr_asm_model_vtable, OWN_2720.parts_model_vtable, OWN_2720.mtx44_entity_vtable), (Some(0x2b37a70), Some(0x2b38808), Some(0x2b70e68)));
        assert_eq!((OWN_2710.chr_asm_model_vtable, OWN_2710.parts_model_vtable, OWN_2710.mtx44_entity_vtable), (None, None, None));
        assert!(scaleform_ui_sites(ExeBuild::Ww2710).is_empty(), "None has no site");
        for b in ExeBuild::ALL {
            let sites = scaleform_ui_sites(b);
            let Some(u) = b.own().scaleform_ui else { continue };
            // every Some address is a site of the same build with the matching kind, and the hook windows are the
            // prologues MinHook re-checks
            for (n, rva, check) in [
                ("scaleform_ui_begin", u.ui_begin, Check::Code(u.ui_begin_prologue)),
                ("scaleform_ui_end", u.ui_end, Check::Code(u.ui_end_prologue)),
                ("scaleform_fs_hal_vtable", u.fs_hal_vtable, Check::VtableNoRtti),
                ("scaleform_g_render", u.g_render, Check::Writable),
                ("scaleform_direct_queue", u.direct_queue, Check::Writable),
            ] {
                let s = sites.iter().find(|s| s.name == n).unwrap_or_else(|| panic!("{b:?}: no C4 site {n}"));
                assert_eq!((s.rva as usize, s.check, s.group, s.conf), (rva, check, Group::Own, Conf::Verified), "{b:?} {n}");
                // never in the boot preflight table (C4 off = the boot preflight unchanged)
                assert!(site(b, n).is_none(), "{b:?} {n} is not a boot site");
            }
            assert_eq!(sites.len(), 5);
            assert_eq!(role(&sites[0]), Role::Hook);
            assert_eq!((u.ui_begin_prologue.len(), u.ui_end_prologue.len()), (16, 16));
        }
        assert_eq!(
            (SCALEFORM_UI_2720.ui_begin, SCALEFORM_UI_2720.ui_end, SCALEFORM_UI_2720.fs_hal_vtable, SCALEFORM_UI_2720.g_render, SCALEFORM_UI_2720.direct_queue),
            (0xd80900, 0xd80a70, 0x2c0bb40, 0x47f6400, 0x4808340)
        );
        // the C3 BeginScene / EndScene the probe also hooks, unchanged by C4
        assert_eq!((OWN_2720.begin_scene, OWN_2720.end_scene), (0x115fda0, 0x115ff00));
    }

    #[test]
    fn c6_depth_addrs_and_sites() {
        // C6 round 6: the aim-camera getter sites on 2.7.2.0 only
        assert_eq!((OWN_2720.aim_cam, OWN_2710.aim_cam), (Some(crate::aim_cam::AIM_CAM_2720), None));
        assert_eq!((OWN_2720.carrier, OWN_2710.carrier), (Some(crate::carrier::CARRIER_2720), None));
        let a = OWN_2720.er_depth.expect("2.7.2.0 has the depth chain");
        assert_eq!(a, crate::er_depth::ER_DEPTH_2720);
        assert_eq!((a.rs_global, a.rs_vt, a.ctx_off, a.ctx_vt, a.ctx_vt2), (0x47f67c8, 0x2f10500, 0x50, 0x2f12638, 0x2f12658));
        assert_eq!((a.dsb, a.dsb_alias, a.tile, a.dsb_vt, a.count_slot, a.count_fn), (0xa70, 0xa88, 0xa78, 0x2f275c0, 0x38, 0x19f3dc0));
        assert_eq!((a.tex, a.arr, a.obj_wrap, a.wrap_res, a.def_ds), (0x40, 0x70, 8, 0x20, 0xe8));
        // the count is computed exactly as the C4.1 chain's (the same slot-7 function)
        let c = UI41_2720;
        assert_eq!((a.count_fn, a.count_slot, a.tex, a.tex_desc, a.desc_data, a.desc_count, a.tex_count), (c.sel_vt_count, c.sel_count_slot, c.sel_tex, c.tex_desc, c.desc_data, c.desc_count, c.tex_count));
        // the GX wrapper -> resource hops are UiBegin's (UiLayout wrap / res)
        assert_eq!((a.obj_wrap, a.wrap_res), (SCALEFORM_UI_2720.layout.wrap, SCALEFORM_UI_2720.layout.res));
        assert_eq!(OWN_2710.er_depth, None);
        assert!(er_depth_sites(ExeBuild::Ww2710).is_empty());
        let sites = er_depth_sites(ExeBuild::Ww2720);
        assert_eq!(sites.len(), 6);
        for s in &sites {
            assert!(site(ExeBuild::Ww2720, s.name).is_none(), "{} is not a boot site", s.name);
            assert_eq!((s.group, s.conf), (Group::Own, Conf::Verified));
        }
        assert_eq!(sites.iter().filter(|s| matches!(s.check, Check::Vmt(_))).count(), 4);
    }

    #[test]
    fn c4_addrs41_tables_and_sites() {
        let c = SCALEFORM_UI_2720.ui41;
        assert_eq!(c, UI41_2720);
        assert_eq!((c.g_mt, c.g_rt, c.rt_tid), (0x11c, 0x6d0, 0x14));
        assert_eq!((c.sel_vt, c.sel_vt_count, c.sel_count_slot), (0x2f0ae60, 0x19f3dc0, 0x38));
        assert_eq!((c.sub_vt, c.sub_slot0, c.sub_slot1), (0x2f0af48, 0x19f49a0, 0x19f4970));
        assert_eq!((c.sel_tex, c.sel_arr, c.tex_desc, c.desc_data, c.desc_count, c.tex_count, c.obj_rtv), (0x40, 0x78, 0x38, 8, 8, 0x46, 0x10));
        assert_eq!((c.owner_rt, c.rt_data, c.rtdata_fmt, c.rtdata_rtv), (0xdd0, 0x20, 0x20, 0x28));
        assert_eq!((c.g_eb9, c.g_scale, c.g_shaders, c.shaders_ready), (0xeb9, 0xed0, 0x740, 8));
        // the sub-object is the C4 getter's `this`: the secondary vtable sits at UiLayout::obj, and the getter's
        // `cmp qword [rcx-30h],0` is `[sel + obj - 0x30]` = T
        assert_eq!(SCALEFORM_UI_2720.layout.obj - 0x30, c.sel_tex);
        assert_eq!(SCALEFORM_UI_2720.layout.obj + 8, c.sel_arr, "slot 0's [rcx+8]");
        // pinned from the 2026-10-21 probe + injection runs (design 3.2)
        assert_eq!(SCALEFORM_UI_2720.layer_alpha, Some(crate::c4::LayerAlpha::Transmit));
        assert!(scaleform_ui41_sites(ExeBuild::Ww2710).is_empty());
        let sites = scaleform_ui41_sites(ExeBuild::Ww2720);
        let want = [
            ("scaleform_sel_vtable", c.sel_vt, Role::Data),
            ("scaleform_sub_vtable", c.sub_vt, Role::Data),
            ("scaleform_sel_count", c.sel_vt_count, Role::Hook),
            ("scaleform_sub_slot0", c.sub_slot0, Role::Hook),
            ("scaleform_sub_slot1", c.sub_slot1, Role::Hook),
        ];
        assert_eq!(sites.len(), want.len());
        for (s, (n, rva, r)) in sites.iter().zip(want) {
            assert_eq!((s.name, s.rva as usize, s.group, s.conf, role(s)), (n, rva, Group::Own, Conf::Verified, r));
            assert!(site(ExeBuild::Ww2720, n).is_none(), "{n} is not a boot site");
            match s.check {
                Check::Code(b) => assert_eq!(b.len(), 16, "{n}"),
                Check::Vmt(t) => assert_eq!(t, GX_RENDER_TARGET_2D, "{n}"),
                other => panic!("{n}: {other:?}"),
            }
        }
        // the C4 sites are unchanged by C4.1 (separate list)
        assert_eq!(scaleform_ui_sites(ExeBuild::Ww2720).len(), 5);
        // the getter window starts with the bytes the C4 probe logged
        let Check::Code(g) = sites[4].check else { unreachable!() };
        assert_eq!(g, &[0x48, 0x83, 0xec, 0x28, 0x48, 0x83, 0x79, 0xd0, 0x00, 0x48, 0xc7, 0x44, 0x24, 0x30, 0x00, 0x00]);
    }

    #[test]
    fn c4_addrs_layout_values() {
        let l = UI_LAYOUT_2720;
        assert_eq!((l.owner_hal, l.owner_movies, l.hal_rtid, l.hal_flags), (0x968, 0xbe0, 0x50, 0x58));
        assert_eq!((l.hal_device, l.hal_queue, l.hal_list), (0x1410, 0x1418, 0x1420));
        assert_eq!((l.s_off, l.scene, l.layer, l.hdr_a, l.hdr_b), (0x128, 0xf0, 0x100, 0x13c, 0x13e));
        assert_eq!((l.obj, l.wrap, l.res), (0x70, 8, 0x20));
        // the UiBegin prologue itself pins owner_hal: `mov rcx,[rcx+968h]` is its last 7 bytes
        let p = SCALEFORM_UI_2720.ui_begin_prologue;
        assert_eq!(&p[9..16], &[0x48, 0x8b, 0x89, 0x68, 0x09, 0x00, 0x00]);
        assert_eq!(u32::from_le_bytes([p[12], p[13], p[14], p[15]]) as usize, l.owner_hal);
        // UiEnd's `mov rsi,[rcx+968h]` starts at +10 (the window ends inside its disp32)
        let e = SCALEFORM_UI_2720.ui_end_prologue;
        assert_eq!(&e[10..16], &[0x48, 0x8b, 0xb1, 0x68, 0x09, 0x00]);
    }

    /// A tiny synthetic image: .text at 0x1000 (exec), .rdata at 0x2000, .data at 0x3000.
    struct Fake {
        mem: Vec<u8>,
        base: u64,
    }

    impl ImageView for Fake {
        fn base(&self) -> u64 {
            self.base
        }
        fn size_of_image(&self) -> u32 {
            self.mem.len() as u32
        }
        fn section_flags(&self, rva: u32) -> Option<u32> {
            match rva {
                0x1000..=0x1fff => Some(SCN_EXEC | SCN_READ | 0x20),
                0x2000..=0x2fff => Some(SCN_READ | 0x40),
                0x3000..=0x3fff => Some(SCN_READ | SCN_WRITE | 0x40),
                _ => None,
            }
        }
        fn read(&self, rva: u32, out: &mut [u8]) -> bool {
            let a = rva as usize;
            match self.mem.get(a..a + out.len()) {
                Some(s) => {
                    out.copy_from_slice(s);
                    true
                }
                None => false,
            }
        }
    }

    fn fake() -> Fake {
        let base = 0x7ff6_0000_0000u64;
        let mut mem = vec![0u8; 0x4000];
        mem[0x1100..0x1104].copy_from_slice(&[0x40, 0x53, 0x48, 0x83]);
        // vtable at 0x2100 with COL at 0x2200 and type descriptor at 0x2300
        mem[0x20f8..0x2100].copy_from_slice(&(base + 0x2200).to_le_bytes());
        mem[0x2100..0x2108].copy_from_slice(&(base + 0x1100).to_le_bytes());
        mem[0x2108..0x2110].copy_from_slice(&(base + 0x1100).to_le_bytes());
        mem[0x2200..0x2204].copy_from_slice(&1u32.to_le_bytes());
        mem[0x220c..0x2210].copy_from_slice(&0x2300u32.to_le_bytes());
        mem[0x2214..0x2218].copy_from_slice(&0x2200u32.to_le_bytes());
        mem[0x2310..0x2310 + 16].copy_from_slice(b".?AVChrCam@CS@@\0");
        Fake { mem, base }
    }

    fn st(rva: u32, check: Check) -> Site {
        Site { name: "t", rva, check, group: Group::Crate, conf: Conf::Verified }
    }

    #[test]
    fn exe_build_site_checks() {
        let f = fake();
        assert_eq!(check_site(&f, &st(0x1100, Check::Code(&[0x40, 0x53, 0x48, 0x83]))), Ok(()));
        assert!(check_site(&f, &st(0x1100, Check::Code(&[0x40, 0x53, 0x48, 0x84]))).unwrap_err().contains("!="));
        assert!(check_site(&f, &st(0x2100, Check::Code(&[0, 0]))).unwrap_err().contains("section"), "code outside exec");
        assert_eq!(check_site(&f, &st(0x2100, Check::Vmt(".?AVChrCam@CS@@"))), Ok(()));
        assert!(check_site(&f, &st(0x2100, Check::Vmt(".?AVChrIns@CS@@"))).unwrap_err().contains("RTTI type"));
        assert!(check_site(&f, &st(0x2100, Check::Vmt(".?AVChrCam@CS"))).is_err(), "prefix is not a match");
        assert!(check_site(&f, &st(0x2108, Check::Vmt(".?AVChrCam@CS@@"))).is_err(), "off by one slot");
        assert_eq!(check_site(&f, &st(0x2100, Check::VtableNoRtti)), Ok(()));
        assert!(check_site(&f, &st(0x2200, Check::VtableNoRtti)).is_err());
        assert_eq!(check_site(&f, &st(0x3010, Check::Writable)), Ok(()));
        assert!(check_site(&f, &st(0x2010, Check::Writable)).is_err());
        assert!(check_site(&f, &st(0x1010, Check::ReadOnly)).is_err());
        assert!(check_site(&f, &st(0, Check::Exec)).unwrap_err().contains("unresolved"));
        assert!(check_site(&f, &st(0x9000_0000, Check::Exec)).unwrap_err().contains("unresolved"));
        // the real tables fail on the fake image (nothing silently passes)
        for b in ExeBuild::ALL {
            let p = preflight(b, &f);
            assert!(!p.passed() && p.failures.len() >= 100, "{b:?}: {}", p.failures.len());
        }
    }

    #[test]
    fn exe_build_roles_and_header() {
        for b in ExeBuild::ALL {
            let names: Vec<&str> = b.sites().iter().map(|s| s.name).collect();
            // every listed name is a crate code site of every build (a typo would silently make a site fatal / unused)
            for n in UNUSED_CRATE_CODE.iter().chain(CALLED_CRATE_CODE.iter()) {
                let s = site(b, n).unwrap_or_else(|| panic!("{b:?}: no site {n}"));
                assert_eq!(s.group, Group::Crate, "{b:?} {n}");
                assert!(matches!(s.check, Check::Code(_) | Check::Exec), "{b:?} {n}");
            }
            assert!(UNUSED_CRATE_CODE.iter().all(|n| !CALLED_CRATE_CODE.contains(n)));
            // every crate code site is classified as exactly one of the two lists
            for s in b.sites().iter().filter(|s| s.group == Group::Crate && matches!(s.check, Check::Code(_) | Check::Exec)) {
                let r = role(s);
                assert!(r == Role::Unused || r == Role::Call, "{b:?} {}", s.name);
                assert_eq!(r == Role::Call, CALLED_CRATE_CODE.contains(&s.name), "{b:?} {}: unlisted crate code site", s.name);
            }
            for n in ["camera_step", "follow_cam", "scaleform_begin_scene", "scaleform_end_scene"] {
                assert_eq!(role(site(b, n).unwrap()), Role::Hook, "{b:?} {n}");
            }
            for n in ["cam_wall_recovery", "cs_collision_filter_vmt", "chr_cam_vmt"] {
                assert_eq!(role(site(b, n).unwrap()), Role::Data, "{b:?} {n}");
            }
            assert!(names.len() == 113);
            let (t, s) = b.header();
            assert_eq!(check_header(b, t, s), Ok(()));
            assert!(check_header(b, t ^ 1, s).is_err());
            assert!(check_header(b, t, s + 0x1000).is_err());
        }
        assert_eq!(ExeBuild::Ww2720.header(), (0x6aabf7e7, 0x5dfd600));
        assert_eq!(ExeBuild::Ww2710.header(), (0x6a96b418, 0x5e0da00));
        let (t, s) = ExeBuild::Ww2710.header();
        assert!(check_header(ExeBuild::Ww2720, t, s).is_err(), "the 2.7.1.0 header is not 2.7.2.0's");
    }

    #[test]
    fn exe_build_preflight_roles() {
        let mut f = fake();
        // 0x1100: 40 53 48 83 then 12 more bytes (a 16-byte window)
        let win: [u8; 16] = [0x40, 0x53, 0x48, 0x83, 0xec, 0x20, 0x48, 0x8b, 0xd9, 0x48, 0x8b, 0x49, 0x08, 0x33, 0xc0, 0xc3];
        f.mem[0x1100..0x1110].copy_from_slice(&win);
        let w: &'static [u8] = Box::leak(Box::new(win));
        let mk = |name: &'static str, group| Site { name, rva: 0x1100, check: Check::Code(w), group, conf: Conf::Verified };
        let unused = mk("cs_ez_draw_draw_line", Group::Crate);
        let called = mk("cs_phys_world_cast_ray", Group::Crate);
        let hook = mk("camera_step", Group::Own);
        let all = [unused, called, hook];
        assert!(preflight_sites(&all, &f).passed());
        assert!(preflight_sites(&all, &f).summary().ends_with("warn=0"));

        // a 5-byte jmp rel32 detour: tolerated on the unused and the called site, fatal on the hook
        f.mem[0x1100..0x1105].copy_from_slice(&[0xe9, 0x10, 0x20, 0x30, 0x40]);
        let p = preflight_sites(&all, &f);
        assert_eq!(p.warnings.len(), 2, "{:?}", p.warnings);
        assert!(p.warnings[1].contains("detoured"), "{:?}", p.warnings);
        assert_eq!(p.failures.len(), 1);
        assert!(p.failures[0].starts_with("camera_step"));
        assert!(preflight_sites(&all[..2], &f).passed(), "unused + called pass with WARN");

        // different code past the detour: the called site fails, the unused one only warns
        f.mem[0x110a] ^= 0xff;
        let p = preflight_sites(&all[..2], &f);
        assert_eq!((p.warnings.len(), p.failures.len()), (1, 1), "{p:?}");
        assert!(p.failures[0].starts_with("cs_phys_world_cast_ray"));
        f.mem[0x110a] ^= 0xff;

        // an unused site outside executable code still fails (a wrong table, not a patch)
        let moved = Site { rva: 0x2100, ..unused };
        assert!(!preflight_sites(&[moved], &f).passed());
        // an unknown crate code name is a called site (fatal), never silently unused
        assert_eq!(role(&mk("some_new_function", Group::Crate)), Role::Call);
    }
}
